import {buildingDesignCanvas} from './building-designs.js?v=disaster-relief-1';
import {baseZonedSprite,zonedSprite,REPLACEABLE_STYLES,replaceBuildingStyle,canReplaceBuilding} from './building-art.js?v=disaster-relief-1';
export {canReplaceBuilding} from './building-art.js?v=disaster-relief-1';
function preview(renderer,index){const s=renderer.sprites[index];if(!s)return '';const canvas=document.createElement('canvas');canvas.width=180;canvas.height=200;const ctx=canvas.getContext('2d'),scale=Math.min(160/s.w,180/s.h);ctx.drawImage(s.atlas,s.x,s.y,s.w,s.h,(180-s.w*scale)/2,190-s.h*scale,s.w*scale,s.h*scale);return canvas.toDataURL('image/png');}
export function showBuildingReplacement({city,renderer,dialog,apply,back},tile){
 const source=baseZonedSprite(tile,city.seed),current=zonedSprite(tile,city.seed,city.buildingReplacements),style=REPLACEABLE_STYLES[source],count=city.tiles.filter(t=>canReplaceBuilding(t)&&baseZonedSprite(t,city.seed)===source).length;
 dialog('Replace building style',`<p>Replace every instance of <strong>${style.name}</strong> in this city: ${count} current buildings. Future buildings of this style use the replacement too. Population, jobs, costs and zoning stay the same.</p><div class="replacement-previews"><div><h3>Original style</h3><img src="${preview(renderer,source)}" alt="${style.name}"></div><div><h3>Selected replacement</h3><img id="replacementPreview" src="${city.buildingDesigns?.[source]?buildingDesignCanvas(city.buildingDesigns[source]).toDataURL('image/png'):preview(renderer,current)}" alt="${city.buildingDesigns?.[source]?'Custom building model':REPLACEABLE_STYLES[current].name}"></div></div><label>Building style<select id="replacementStyle">${Object.entries(REPLACEABLE_STYLES).filter(([,v])=>v.group===style.group).map(([key,v])=>`<option value="${key}" ${Number(key)===current?'selected':''}>${v.name}</option>`).join('')}</select></label><div class="actions"><button id="applyReplacement" class="primary">Apply to every instance</button><button id="revertReplacement" ${current===source&&!city.buildingDesigns?.[source]?'disabled':''}>Revert original style</button><button id="cancelReplacement">Cancel</button></div><p class="fine">The replacement library covers 14 existing residential, commercial and non-farm industrial styles. Replacements stay within the same zone family, but may have a different visual height. Farms keep their connected barn and field artwork. Use City desk → Building designer to create or import a custom model. The full replacement catalog remains unfinished.</p>`);
 const select=document.querySelector('#replacementStyle');select.onchange=()=>{const image=document.querySelector('#replacementPreview'),value=Number(select.value);image.src=preview(renderer,value);image.alt=REPLACEABLE_STYLES[value].name;};
 const commit=target=>{replaceBuildingStyle(city,source,target);apply();back();};document.querySelector('#applyReplacement').onclick=()=>commit(Number(select.value));document.querySelector('#revertReplacement').onclick=()=>commit(source);document.querySelector('#cancelReplacement').onclick=back;
}
